-- Tailmance v19 R8 configured-27 all-supported-language jurisdiction supplement coverage.
-- Extends source-level legal/language approval from required binding document locales to every supported legal-document locale.
-- Accessibility translations never replace a binding language where law/configured route requires one.

alter table public.legal_jurisdiction_policies
  add column if not exists source_accessibility_document_locales text[] not null default '{}'::text[];

update public.legal_jurisdiction_policies
set source_accessibility_document_locales=array['ar','ca','de','en','es','eu','fr','gl','hi','id','it','ja','ko','nl','pl','pt-BR','ru','th','tr','vi','zh-Hans','zh-Hant']::text[],updated_by='v19_134_all_language_source_coverage',updated_at=now()
where legal_country_code=any(array['AE','AT','AU','BE','BR','CA','CN','DE','ES','FR','GB','ID','IE','IN','IT','JP','KR','NL','PL','RU','SA','SG','TH','TR','TW','US','VN']::text[]);

alter table public.legal_jurisdiction_policies drop constraint if exists legal_jurisdiction_source_accessibility_coverage_ck;
alter table public.legal_jurisdiction_policies add constraint legal_jurisdiction_source_accessibility_coverage_ck check (
  source_legal_review_status<>'approved_internal_official_source_review' or (
    cardinality(source_accessibility_document_locales)=22 and
    source_approved_document_locales <@ source_accessibility_document_locales
  )
);

alter table public.legal_country_source_document_supplements
  add column if not exists route_role text not null default 'required_binding_document_locale',
  add column if not exists required_binding_locale boolean not null default true;
alter table public.legal_country_source_document_supplements drop constraint if exists legal_country_source_document_supplements_route_role_ck;
alter table public.legal_country_source_document_supplements add constraint legal_country_source_document_supplements_route_role_ck check (
  (required_binding_locale and route_role='required_binding_document_locale') or
  (not required_binding_locale and route_role='accessibility_translation_non_controlling')
);

