on conflict (legal_country_code,document_locale) do update set
  document_version=excluded.document_version,source_path=excluded.source_path,source_sha256=excluded.source_sha256,
  public_relative_path=excluded.public_relative_path,public_sha256=excluded.public_sha256,official_source_count=excluded.official_source_count,
  internal_language_qa_status=excluded.internal_language_qa_status,route_role=excluded.route_role,required_binding_locale=excluded.required_binding_locale,
  internal_review_evidence_reference=excluded.internal_review_evidence_reference,reviewed_at=excluded.reviewed_at,valid_until=excluded.valid_until,reviewed_by=excluded.reviewed_by;

create or replace function public.legal_source_approval_current(p_country_code text)
returns boolean language plpgsql stable security definer set search_path='' as $$
declare v public.legal_jurisdiction_policies;v_expected_binding integer;v_actual_binding integer;v_expected_access integer;v_actual_access integer;
begin
  if p_country_code is null or upper(trim(p_country_code)) !~ '^[A-Z]{2}$' then return false; end if;
  select * into v from public.legal_jurisdiction_policies where legal_country_code=upper(trim(p_country_code));
  if not found then return false; end if;
  if v.source_legal_review_status<>'approved_internal_official_source_review'
     or v.source_language_review_status<>'approved_internal_legal_language_qa'
     or v.source_reviewed_at is null or v.source_reviewed_at>now()+interval '5 minutes'
     or v.source_review_valid_until is null or v.source_review_valid_until<=now()
     or jsonb_array_length(v.source_review_evidence_reference)=0
     or jsonb_array_length(v.source_language_review_evidence_reference)=0
     or cardinality(v.source_approved_document_locales)=0
     or cardinality(v.source_accessibility_document_locales)<>22
     or not (v.source_approved_document_locales <@ v.source_accessibility_document_locales) then return false; end if;
  v_expected_binding:=cardinality(v.source_approved_document_locales);
  select count(*) into v_actual_binding from public.legal_country_source_document_supplements d
   where d.legal_country_code=v.legal_country_code and d.document_locale=any(v.source_approved_document_locales)
     and d.required_binding_locale and d.route_role='required_binding_document_locale'
     and d.internal_language_qa_status='complete_internal_reviewed'
     and d.reviewed_at<=now()+interval '5 minutes' and d.valid_until>now()
     and jsonb_array_length(d.internal_review_evidence_reference)>0;
  if v_actual_binding<>v_expected_binding then return false; end if;
  v_expected_access:=cardinality(v.source_accessibility_document_locales);
  select count(*) into v_actual_access from public.legal_country_source_document_supplements d
   where d.legal_country_code=v.legal_country_code and d.document_locale=any(v.source_accessibility_document_locales)
     and d.internal_language_qa_status='complete_internal_reviewed'
     and d.reviewed_at<=now()+interval '5 minutes' and d.valid_until>now()
     and jsonb_array_length(d.internal_review_evidence_reference)>0;
  return v_actual_access=v_expected_access;
end $$;
revoke all on function public.legal_source_approval_current(text) from public,anon,authenticated;
grant execute on function public.legal_source_approval_current(text) to service_role;

create or replace function public.legal_country_supplement_source_route(p_country_code text,p_document_locale text)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare d public.legal_country_source_document_supplements;
begin
  if p_country_code is null or p_document_locale is null then return jsonb_build_object('status','blocked_missing_context'); end if;
  select * into d from public.legal_country_source_document_supplements
   where legal_country_code=upper(trim(p_country_code)) and document_locale=trim(p_document_locale)
     and internal_language_qa_status='complete_internal_reviewed' and reviewed_at<=now()+interval '5 minutes' and valid_until>now();
  if not found then return jsonb_build_object('status','blocked_country_language_supplement_missing'); end if;
  return jsonb_build_object('status','ready','legalCountryCode',d.legal_country_code,'documentLocale',d.document_locale,
    'publicRelativePath',d.public_relative_path,'documentVersion',d.document_version,'publicSha256',d.public_sha256,
    'routeRole',d.route_role,'requiredBindingLocale',d.required_binding_locale);
end $$;
revoke all on function public.legal_country_supplement_source_route(text,text) from public,anon,authenticated;
grant execute on function public.legal_country_supplement_source_route(text,text) to service_role;
